import{_ as l,l as r,o as e,c as s,v as t,p as d,x as o,d as D,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"三维胶模型","description":"","frontmatter":{"title":"三维胶模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/3d-resist-model.md","filePath":"litho/3d-resist-model.md","lastUpdated":1789023840000}'),p={name:"litho/3d-resist-model.md"};function E(c,a,m,_,A,u){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="三维胶模型" tabindex="-1">三维胶模型 <a class="header-anchor" href="#三维胶模型" aria-label="Permalink to &quot;三维胶模型&quot;">​</a></h1><div class="epigraph"><p>2D 轮廓假定胶是无限薄的刀；真实胶有厚度、侧壁角和顶损失，转印看到的是这截三维物体。</p><footer>—— 对照三维抗蚀剂剖面模拟与紧凑 2D 轮廓签核的公开讨论</footer></div><p><a href="/litho/model-residual-analysis">上一课</a>在 2D EPE 上诊断残差。缺口是转印与电学有时对侧壁和剩余厚度敏感：塌缩、开口不足、硬掩模打穿。本课钉三维胶模型。刻蚀核如何标定，留给[下一课](/litho/etch-model-calibration）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/resist-compact-model">胶紧凑模型</a> 输出平面轮廓，全芯片 OPC 靠它。三维模型（反应–扩散 + 显影速率沿 z，或经验侧壁角）解释 FEM 截面、顶圆化、T-top、底脚。高 NA 薄胶与 EUV 吸收浅，z 方向自由度变少，但相对误差对转印更大——见薄胶转印课的衔接，本课不重写光子吸收。</p><p>缺口是<strong>何时 2D 不够</strong>，不是每层都上 3D 全芯片。把截面 SEM 当 OPC 目标，算力与计量都会炸。</p><h3 id="_3d-是签核补充-不是替代-cm" tabindex="-1">3D 是签核补充，不是替代 CM <a class="header-anchor" href="#_3d-是签核补充-不是替代-cm" aria-label="Permalink to &quot;3D 是签核补充，不是替代 CM&quot;">​</a></h3><p>热区、新胶、新 NA 用 3D 解释 2D 残差中的焦点不对称与「CD 对了但刻不穿」。日常 TAPOUT 仍是 2D CM + 刻蚀核。3D 校准集是截面与 AFM，样本少，过拟合风险高。</p><p><span class="marginnote">显影后侧壁角进入刻蚀开口；2D EPE 为零仍可能 ARDE 或打穿失败。AEI 目标要声明是顶 CD 还是电学 CD。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验室：PROLITH 一类或内部 3D 求解器，用 Dill/Mack 参数加 PEB。紧凑 3D：对 2D 边附加角与高度的经验映射，由截面校准。与 <a href="/litho/resist-profile-simulation">抗蚀剂剖面仿真</a> 的关系：那课写剖面物理；本课写它在模型栈里的位置——校准后的 2D 签核何时必须加 3D 抽检。</p><p>EUV 二次电子模糊在 z 与 xy 都有，3D 模糊核与 2D 有效模糊不是简单切片。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>曝光在 z 上随吸收指数衰减（DUV 更明显，EUV 也非均匀），显影前沿从表面推进，形成角。驻波（薄膜课已有）给出 z 调制，截面呈波纹。紧凑 2D 把这些积分成分成「有效边」；当转印阈值落在剖面某处而不是「平均边」时，积分失效。</p>',14)),(e(),d(h,null,{default:o(()=>[n(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%203D%22%5D%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%89%8D%E6%B2%BF%22%5D%0A%20%20DEV%20--%3E%20PROF%5B%22%E8%83%B6%E5%89%96%E9%9D%A2%22%5D%0A%20%20PROF%20--%3E%20CD2%5B%22%E6%9C%89%E6%95%88%202D%20%E8%BE%B9%22%5D%0A%20%20PROF%20--%3E%20ETCH%5B%22%E8%BD%AC%E5%8D%B0%E5%BC%80%E5%8F%A3%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[D(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>3D 胶模型不替代等离子体腔体。全芯片 3D 反应–扩散仍不可作 OPC 内循环。不编造某胶的侧壁角度数表。</p><p>后课默认：ADI 可以是 2D 边加抽检剖面；下一课把 AEI 当作第二个要校准的邻域算子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2D CM 是全芯片默认；3D 胶解释剖面敏感的转印与焦点不对称。</li><li>高 NA 薄胶让 z 误差更致命，但仍不是全芯片 3D OPC。</li><li>截面计量样本少，3D 经验项易过拟合。</li><li>出处：Mack 三维显影与剖面；紧凑 2D 对 3D 的工程分工。</li></ul>',5))])}const B=l(p,[["render",E]]);export{f as __pageData,B as default};
